config.script:
// confirmacao_diaria — agente `script` (MACRO). Comportamento = ESTE arquivo (DADO).
//
// UMA vez por dia (trigger cron), junta os agendamentos ainda NÃO confirmados pelo paciente
// (sem RSVP, não confirmados pela recepção, públicos, fora de status terminal) dentro de uma
// JANELA que vai de HOJE até o PRÓXIMO DIA DE ENVIO — e dispara UMA campanha WhatsApp com o
// HSM `confirmar_presenca` (1 destinatário por agendamento). A RESPOSTA do botão volta sozinha
// pelo time `confirmacao-presenca`.
//
// JANELA / DIAS SEM ENVIO (config `dias_sem_envio`, default [0,6] = domingo e sábado):
//   - Se HOJE é um dia sem envio, o agente NÃO dispara nada (loga e sai limpo).
//   - Senão, a janela vai de hoje até o próximo dia de envio a partir de amanhã (inclusive).
//     Com o default, seg–qui cobre hoje+amanhã; SEXTA cobre sexta+sábado+domingo+segunda.
//
// RESULTADO (result()): o agente declara um RESUMO SEGURO (contagens/flags, sem PII) que
// aparece no drill-down da execução na Central — pra o operador acompanhar sem ler log.
// Também marca `acao_bloqueada` quando uma call() falha (ex.: egress off) — assim um agente
// sandboxado/quebrado NÃO se disfarça de "0 pendentes / ok".
//
// PERSONALIZAÇÃO (obrigatória p/ o HSM): a Meta exige TODOS os 4 params não-vazios; o agente
// resolve cliente_nome (1º nome) + profissional_apelido, pega servico_nome (NOME DO PACOTE
// quando é pacote) e formata data_hora — sempre com fallback não-vazio.
//
// Injetados: event, config, context, call()->{ok,status_code,body}, log(), result().

var cfg = config || {};
var minLeadMin = (cfg.min_lead_minutos !== undefined && cfg.min_lead_minutos !== null) ? cfg.min_lead_minutos : 120;
var tzOffset = cfg.tz_offset || '-03:00';
var statusPular = cfg.status_pular || ['Cancelado', 'Falta', 'Atendido', 'Realizado'];
var diasSemEnvio = cfg.dias_sem_envio || [0, 6]; // 0=domingo ... 6=sábado (fuso da clínica)
var perPage = cfg.per_page || 100;
var canalPolicy = cfg.canal_policy || 'so_whatsapp';
var templateSlug = cfg.template_slug || 'confirmar_presenca';
var nomeCampanha = cfg.nome_campanha || 'Confirmação diária';
var LOTE_MAX = 500;
var MAX_PAGINAS = 30;
var DIA_MS = 86400000;

function unwrap(r) {
  if (!r || !r.ok) return null;
  var b = r.body;
  return (b && b.data !== undefined) ? b.data : b;
}
function offsetMin(s) {
  var m = /^([+-])(\d{2}):(\d{2})$/.exec(String(s));
  if (!m) return -180;
  var val = parseInt(m[2], 10) * 60 + parseInt(m[3], 10);
  return m[1] === '-' ? -val : val;
}
function pad(n) { return (n < 10 ? '0' : '') + n; }
function partesLocais(ms) {
  var d = new Date(ms + offsetMin(tzOffset) * 60000);
  return {
    data: d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate()),
    dia: pad(d.getUTCDate()), mes: pad(d.getUTCMonth() + 1),
    hh: pad(d.getUTCHours()), mm: pad(d.getUTCMinutes())
  };
}
// Dia da semana LOCAL (fuso da clínica): 0=domingo ... 6=sábado.
function diaSemanaLocal(ms) {
  return new Date(ms + offsetMin(tzOffset) * 60000).getUTCDay();
}
function dataHoraBR(p) { return p.dia + '/' + p.mes + ' às ' + p.hh + ':' + p.mm; }

// Nome do serviço p/ a mensagem: NOME DO PACOTE quando é pacote; senão procedimento/produto.
function servicoNome(ag) {
  var venda = ag.venda;
  if (!venda || !venda.itens || !venda.itens.length) return null;
  for (var i = 0; i < venda.itens.length; i++) {
    if (venda.itens[i] && venda.itens[i].pacote_nome) return venda.itens[i].pacote_nome;
  }
  for (var j = 0; j < venda.itens.length; j++) {
    var it = venda.itens[j] || {};
    if (it.procedimento_nome) return it.procedimento_nome;
    if (it.produto_nome) return it.produto_nome;
  }
  return null;
}

// --- enrich: 1º nome do paciente + apelido do profissional (com cache) ---
function primeiroNome(nome) {
  var s = String(nome || '').trim();
  if (!s) return null;
  var i = s.indexOf(' ');
  return i > 0 ? s.substring(0, i) : s;
}
var _cliCache = {};
function clienteNome(id) {
  if (!id) return null;
  var k = String(id);
  if (_cliCache[k] !== undefined) return _cliCache[k];
  var d = unwrap(call('buscar_cliente', { cliente_id: k }));
  _cliCache[k] = (d && d.nome) ? primeiroNome(d.nome) : null;
  return _cliCache[k];
}
var _profCache = {};
function profApelido(id) {
  if (!id) return null;
  var k = String(id);
  if (_profCache[k] !== undefined) return _profCache[k];
  var d = unwrap(call('buscar_profissional', { id: k }));
  _profCache[k] = d ? (d.apelido || d.nome || null) : null;
  return _profCache[k];
}

// ---- referências temporais (epoch absoluto + fuso da clínica) ----
var nowMs = Date.now();

// Set de dias sem envio (fuso da clínica).
var semEnvio = {};
for (var w = 0; w < diasSemEnvio.length; w++) semEnvio[Number(diasSemEnvio[w])] = true;

// HOJE é dia sem envio? -> não dispara nada.
if (semEnvio[diaSemanaLocal(nowMs)]) {
  log('confirmacao_diaria: hoje é dia sem envio (dow=' + diaSemanaLocal(nowMs) + ') — nada disparado');
  result({ pulado: 'dia_sem_envio', dow: diaSemanaLocal(nowMs), campanhas: 0, destinatarios: 0 });
  return { ok: true, pendentes: 0, campanhas: 0, pulado: 'dia_sem_envio', dow: diaSemanaLocal(nowMs) };
}

// Fim da janela = próximo DIA DE ENVIO a partir de amanhã (pula os dias sem envio).
var k = 1;
while (k <= 7 && semEnvio[diaSemanaLocal(nowMs + k * DIA_MS)]) k++;

var cutoffMs = nowMs + minLeadMin * 60000;
var hoje = partesLocais(nowMs).data;
var fimData = partesLocais(nowMs + k * DIA_MS).data;
var ini = hoje + 'T00:00:00' + tzOffset;
var fim = fimData + 'T23:59:59' + tzOffset;

var pular = {};
for (var s = 0; s < statusPular.length; s++) pular[String(statusPular[s]).toLowerCase()] = true;

// ---- 1) coleta paginada + recorte ----
var pendentes = [];
var pagina = 1;
while (pagina <= MAX_PAGINAS) {
  var raw = call('listar_nao_confirmados', {
    data_inicio: ini, data_fim: fim,
    confirmado: 'false', rsvp_cliente: 'sem_resposta',
    per_page: perPage, page: pagina
  });
  // Chamada BLOQUEADA/falhou (egress off, 403, 5xx, timeout) NÃO é "lista vazia": torna
  // visível em vez de fingir 0 pendentes (o agente sandboxado não se disfarça de verde).
  if (raw && !raw.ok) {
    log('confirmacao_diaria: FALHA ao listar (HTTP ' + (raw.status_code || '?') + ' ' + (raw.error || '') + ')');
    result({ acao_bloqueada: true, etapa: 'listar_nao_confirmados', http: raw.status_code || null,
             erro: raw.error || 'chamada não-ok', campanhas: 0, destinatarios: 0 });
    return { ok: false, erro: 'listar_falhou', http: raw.status_code || null };
  }
  var lista = unwrap(raw);
  if (!lista || !lista.length) break;
  for (var kk = 0; kk < lista.length; kk++) {
    var ag = lista[kk];
    if (!ag || !ag.id) continue;
    if (ag.visibilidade && String(ag.visibilidade) !== 'publica') continue;
    if (ag.status && pular[String(ag.status).toLowerCase()]) continue;
    if (!ag.cliente_id) continue;
    var startMs = Date.parse(ag.data_inicio);
    if (isNaN(startMs)) continue;
    var loc = partesLocais(startMs);
    if (loc.data < hoje || loc.data > fimData) continue;       // fora da janela [hoje..fimData]
    if (loc.data === hoje && startMs < cutoffMs) continue;      // hoje respeita o lead mínimo
    ag.__loc = loc;
    pendentes.push(ag);
  }
  if (lista.length < perPage) break;
  pagina++;
}

// contagem por dia (pro resumo do operador).
function contarPorDia(arr) {
  var m = {};
  for (var i = 0; i < arr.length; i++) { var d = arr[i].__loc.data; m[d] = (m[d] || 0) + 1; }
  return m;
}

if (!pendentes.length) {
  log('confirmacao_diaria: nenhum agendamento pendente (janela ' + ini + '..' + fim + ', lead ' + minLeadMin + 'min)');
  result({ pendentes: 0, campanhas: 0, destinatarios: 0, janela: hoje + '..' + fimData });
  return { ok: true, pendentes: 0, campanhas: 0, janela: { de: ini, ate: fim }, min_lead_minutos: minLeadMin };
}

// ---- 2) monta destinatários (1 por agendamento; os 4 params do HSM, não-vazios) ----
var destinatarios = [];
for (var p = 0; p < pendentes.length; p++) {
  var a = pendentes[p];
  var vars = {
    cliente_nome: clienteNome(a.cliente_id) || 'paciente',
    servico_nome: servicoNome(a) || 'consulta',
    profissional_apelido: profApelido(a.profissional_id) || 'a clínica',
    data_hora: dataHoraBR(a.__loc)
  };
  destinatarios.push({
    cliente_id: String(a.cliente_id),
    variaveis: vars,
    referencia_tipo: 'agendamento',
    referencia_id: String(a.id)
  });
}

// ---- 3) dispara em lotes de até 500 ----
var campanhas = 0, enviados = 0, falhaLote = null;
var multi = destinatarios.length > LOTE_MAX;
for (var base = 0; base < destinatarios.length; base += LOTE_MAX) {
  var lote = destinatarios.slice(base, base + LOTE_MAX);
  var nome = nomeCampanha + ' (' + hoje + ')' + (multi ? ' #' + (campanhas + 1) : '');
  var r = call('disparar_campanha', {
    nome: nome,
    canal_policy: canalPolicy,
    template_slug: templateSlug,
    variaveis_base: {},
    destinatarios: lote,
    referencia_tipo: 'agendamento',
    rascunho: false
  });
  if (r && r.ok) { campanhas++; enviados += lote.length; }
  else {
    falhaLote = { http: (r && r.status_code) || null, erro: (r && r.error) || 'disparo não-ok' };
    log('confirmacao_diaria: FALHA no lote ' + (campanhas + 1) + ' HTTP ' + (r && r.status_code));
  }
}

log('confirmacao_diaria: ' + pendentes.length + ' pendente(s) -> ' + campanhas + ' campanha(s), ' + enviados + ' destinatário(s)');
var resumo = {
  pendentes: pendentes.length,
  campanhas: campanhas,
  destinatarios: enviados,
  por_dia: contarPorDia(pendentes),
  janela: hoje + '..' + fimData
};
if (falhaLote) { resumo.acao_bloqueada = true; resumo.etapa = 'disparar_campanha'; resumo.http = falhaLote.http; resumo.erro = falhaLote.erro; }
result(resumo);
return {
  ok: !falhaLote, pendentes: pendentes.length, campanhas: campanhas, destinatarios: enviados,
  janela: { de: ini, ate: fim }, min_lead_minutos: minLeadMin
};
